import React, { useState, useEffect } from 'react';
import {
  Paper,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Box,
  Chip,
  Grid,
  Card,
  CardContent,
  Alert
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  Save,
  Cancel
} from '@mui/icons-material';
import { apiService } from '../../services/realApiService';

const ChecklistsManagement = () => {
  const [checklists, setChecklists] = useState([]);
  const [projects, setProjects] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [editingChecklist, setEditingChecklist] = useState(null);
  const [newChecklist, setNewChecklist] = useState({
    name: '',
    description: '',
    area_id: '',
    project_id: '',
    iatf_code: '',
    questions: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Cargar checklists y proyectos
  const loadData = async () => {
    try {
      setLoading(true);
      
      // Cargar checklists y proyectos en paralelo
      const [checklistsResponse, projectsResponse] = await Promise.all([
        apiService.getAllChecklists(),
        apiService.getProjects()
      ]);

      console.log('📋 Respuesta de checklists:', checklistsResponse.data);
      console.log('🏗️ Respuesta de proyectos:', projectsResponse.data);

      if (checklistsResponse.data.success) {
        setChecklists(checklistsResponse.data.checklists || []);
      }

      if (projectsResponse.data.success) {
        setProjects(projectsResponse.data.projects || []);
      }

    } catch (error) {
      console.error('❌ Error cargando datos:', error);
      setError('Error cargando datos: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreateChecklist = async () => {
    try {
      console.log('➕ Creando checklist:', newChecklist);
      
      // Validar datos mínimos
      if (!newChecklist.name.trim()) {
        setError('El nombre del checklist es obligatorio');
        return;
      }

      // Preparar datos para enviar
      const checklistData = {
        name: newChecklist.name,
        description: newChecklist.description || '',
        project_id: newChecklist.project_id || null,
        iatf_code: newChecklist.iatf_code || '',
        questions: newChecklist.questions || []
      };

      const response = await apiService.createChecklist(checklistData);
      console.log('✅ Checklist creado:', response.data);

      if (response.data.success) {
        await loadData();
        setOpenDialog(false);
        setNewChecklist({
          name: '',
          description: '',
          area_id: '',
          project_id: '',
          iatf_code: '',
          questions: []
        });
      }
    } catch (error) {
      console.error('❌ Error creando checklist:', error);
      setError('Error creando checklist: ' + error.message);
    }
  };

  const handleEditChecklist = (checklist) => {
    console.log('✏️ Editando checklist:', checklist);
    setEditingChecklist(checklist);
    setNewChecklist({ 
      ...checklist,
      // Asegurar que questions sea un array
      questions: Array.isArray(checklist.questions) ? checklist.questions : []
    });
    setOpenDialog(true);
  };

  const handleUpdateChecklist = async () => {
    try {
      console.log('📝 Actualizando checklist:', editingChecklist.id);
      
      if (!newChecklist.name.trim()) {
        setError('El nombre del checklist es obligatorio');
        return;
      }

      const checklistData = {
        name: newChecklist.name,
        description: newChecklist.description || '',
        questions: newChecklist.questions || [],
        iatf_code: newChecklist.iatf_code || ''
      };

      const response = await apiService.updateChecklist(editingChecklist.id, checklistData);
      console.log('✅ Checklist actualizado:', response.data);

      if (response.data.success) {
        await loadData();
        setOpenDialog(false);
        setEditingChecklist(null);
      }
    } catch (error) {
      console.error('❌ Error actualizando checklist:', error);
      setError('Error actualizando checklist: ' + error.message);
    }
  };

  const handleDeleteChecklist = async (id) => {
    if (window.confirm('¿Estás seguro de que quieres eliminar este checklist?')) {
      try {
        const response = await apiService.deleteChecklist(id);
        console.log('🗑️ Checklist eliminado:', response.data);

        if (response.data.success) {
          await loadData();
        }
      } catch (error) {
        console.error('❌ Error eliminando checklist:', error);
        setError('Error eliminando checklist: ' + error.message);
      }
    }
  };

  const handleSaveChecklist = () => {
    if (editingChecklist) {
      handleUpdateChecklist();
    } else {
      handleCreateChecklist();
    }
  };

  const addQuestion = () => {
    setNewChecklist(prev => ({
      ...prev,
      questions: [
        ...prev.questions,
        {
          id: `q${Date.now()}`,
          type: 'boolean',
          text: '',
          image: null
        }
      ]
    }));
  };

  const updateQuestion = (questionId, field, value) => {
    setNewChecklist(prev => ({
      ...prev,
      questions: prev.questions.map(q =>
        q.id === questionId ? { ...q, [field]: value } : q
      )
    }));
  };

  const removeQuestion = (questionId) => {
    setNewChecklist(prev => ({
      ...prev,
      questions: prev.questions.filter(q => q.id !== questionId)
    }));
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">
          Gestión de Checklists
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => {
            setEditingChecklist(null);
            setNewChecklist({
              name: '',
              description: '',
              area_id: '',
              project_id: '',
              iatf_code: '',
              questions: []
            });
            setOpenDialog(true);
          }}
        >
          Nuevo Checklist
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Nombre</TableCell>
              <TableCell>Área</TableCell>
              <TableCell>Proyecto</TableCell>
              <TableCell>Código IATF</TableCell>
              <TableCell>Preguntas</TableCell>
              <TableCell>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  Cargando checklists...
                </TableCell>
              </TableRow>
            ) : checklists.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  No hay checklists creados. Crea el primer checklist.
                </TableCell>
              </TableRow>
            ) : (
              checklists.map((checklist) => (
                <TableRow key={checklist.id}>
                  <TableCell>{checklist.name}</TableCell>
                  <TableCell>
                    <Chip 
                      label={checklist.area_name || 'Sin área'} 
                      size="small" 
                      color={checklist.area_name ? "primary" : "default"}
                    />
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={checklist.project_name || 'Sin proyecto'} 
                      size="small" 
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>
                    {checklist.iatf_code || 'N/A'}
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={Array.isArray(checklist.questions) ? checklist.questions.length : 0}
                      size="small"
                      color="info"
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton
                      color="primary"
                      onClick={() => handleEditChecklist(checklist)}
                    >
                      <Edit />
                    </IconButton>
                    <IconButton
                      color="error"
                      onClick={() => handleDeleteChecklist(checklist.id)}
                    >
                      <Delete />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Diálogo para crear/editar checklist */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          {editingChecklist ? 'Editar Checklist' : 'Crear Nuevo Checklist'}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Nombre del Checklist *"
                value={newChecklist.name}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, name: e.target.value }))}
                required
                error={!newChecklist.name.trim()}
                helperText={!newChecklist.name.trim() ? "Campo requerido" : ""}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Código IATF"
                value={newChecklist.iatf_code}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, iatf_code: e.target.value }))}
                placeholder="Ej: IATF-001"
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Proyecto</InputLabel>
                <Select
                  value={newChecklist.project_id || ''}
                  label="Proyecto"
                  onChange={(e) => setNewChecklist(prev => ({ ...prev, project_id: e.target.value }))}
                >
                  <MenuItem value="">Sin proyecto</MenuItem>
                  {projects.map(project => (
                    <MenuItem key={project.id} value={project.id}>
                      {project.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Descripción"
                multiline
                rows={2}
                value={newChecklist.description || ''}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, description: e.target.value }))}
              />
            </Grid>
          </Grid>

          <Box sx={{ mt: 3 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="h6">Preguntas</Typography>
              <Button onClick={addQuestion} startIcon={<Add />} variant="outlined">
                Agregar Pregunta
              </Button>
            </Box>

            {newChecklist.questions.map((question, index) => (
              <Card key={question.id} sx={{ mb: 2 }}>
                <CardContent>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={12} sm={6}>
                      <TextField
                        fullWidth
                        label={`Pregunta ${index + 1} *`}
                        value={question.text}
                        onChange={(e) => updateQuestion(question.id, 'text', e.target.value)}
                        required
                      />
                    </Grid>
                    <Grid item xs={12} sm={4}>
                      <FormControl fullWidth>
                        <InputLabel>Tipo de respuesta</InputLabel>
                        <Select
                          value={question.type}
                          label="Tipo de respuesta"
                          onChange={(e) => updateQuestion(question.id, 'type', e.target.value)}
                        >
                          <MenuItem value="boolean">Sí/No</MenuItem>
                          <MenuItem value="number">Numérico</MenuItem>
                          <MenuItem value="text">Texto</MenuItem>
                          <MenuItem value="photo">Foto</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={2}>
                      <IconButton
                        color="error"
                        onClick={() => removeQuestion(question.id)}
                      >
                        <Delete />
                      </IconButton>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            ))}

            {newChecklist.questions.length === 0 && (
              <Alert severity="info" sx={{ mt: 2 }}>
                No hay preguntas en este checklist. Agrega al menos una pregunta.
              </Alert>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)} startIcon={<Cancel />}>
            Cancelar
          </Button>
          <Button 
            onClick={handleSaveChecklist} 
            variant="contained" 
            startIcon={<Save />}
            disabled={!newChecklist.name.trim() || newChecklist.questions.length === 0}
          >
            {editingChecklist ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ChecklistsManagement;
